<script setup lang="ts">
import { ref, watch } from 'vue'
import { ShieldCheck, Database, CheckCircle2, CircleAlert, Info, RefreshCw } from 'lucide-vue-next'
import PageHeading from '../components/PageHeading.vue'
import StatePanel from '../components/StatePanel.vue'
import { api, query, type Health } from '../lib/api'
import { useWorkspace } from '../stores/workspace'
import { useAsync } from '../lib/useAsync'
interface Consistency { status: string; checkedSections: number; checkedStudents: number; mismatches: unknown[] }
const workspace = useWorkspace(), { loading, error, run } = useAsync(), health = ref<Health>(), consistency = ref<Consistency>(), checkedAt = ref('')
async function load() { await run(async () => { [health.value, consistency.value] = await Promise.all([api<Health>('/health'), api<Consistency>('/admin/consistency' + query({ termId: workspace.termId }))]); checkedAt.value = new Date().toLocaleString('zh-CN') }) }
watch(() => workspace.termId, load, { immediate: true })
</script>
<template><PageHeading eyebrow="TRUST BUILT ON REAL EVIDENCE" title="运行与一致性" description="真实数据库身份与数据关联校验，为教学工作提供清晰依据。"><select v-model="workspace.termId" class="select-control" aria-label="选择校验学期"><option v-for="term in workspace.terms" :key="term.id" :value="term.id">{{ term.name }}</option></select><button class="button button-secondary" :disabled="loading" @click="load"><RefreshCw :size="14"/>重新检查</button></PageHeading><StatePanel v-if="loading" loading/><StatePanel v-else-if="error" :error="error" @retry="load"/><template v-else-if="health && consistency"><div v-if="health.surrogate" class="notice-banner notice-warning"><CircleAlert :size="16"/><span>当前连接H2辅助演示库。页面功能演示与本地测试不能替代课程目标数据库的真实验收。</span></div><div class="chart-grid"><section class="card card-padding"><div class="row"><span class="aside-icon"><Database :size="19"/></span><h2>当前数据库身份</h2></div><dl class="detail-grid mt-24"><div><dt>配置类型</dt><dd>{{ health.database }}</dd></div><div><dt>连接状态</dt><dd><span class="tag">{{ health.status }}</span></dd></div><div><dt>应用模式版本</dt><dd>{{ health.schemaVersion }}</dd></div><div><dt>辅助演示库</dt><dd>{{ health.surrogate ? '是 · 不计目标库验收' : '否' }}</dd></div><div class="field-full"><dt>数据库实际版本</dt><dd class="backend-detail">{{ health.serverVersion }}</dd></div></dl></section><section class="card card-padding"><div class="row"><span class="aside-icon"><ShieldCheck :size="19"/></span><h2>关联数据一致性</h2></div><div class="row mt-24"><CheckCircle2 v-if="!consistency.mismatches.length" :size="27" class="text-green"/><CircleAlert v-else :size="27" class="text-red"/><div><h3>{{ consistency.mismatches.length ? '检测到不一致记录' : '本次校验未发现不一致' }}</h3><p class="muted" style="font-size:10px;margin-top:5px">{{ checkedAt }}</p></div></div><dl class="detail-grid"><div><dt>已核对教学班</dt><dd>{{ consistency.checkedSections }} 个</dd></div><div><dt>已核对学生</dt><dd>{{ consistency.checkedStudents }} 人</dd></div><div><dt>差异记录</dt><dd>{{ consistency.mismatches.length }} 条</dd></div><div><dt>校验状态</dt><dd>{{ consistency.status }}</dd></div></dl></section></div><div class="notice-banner"><Info :size="16"/><span>本页执行只读聚合核对，不修改人数、学分或选课记录。校验结果反映本次查询时的实际状态。</span></div><section v-if="consistency.mismatches.length" class="card card-padding"><h2>差异详情</h2><pre class="audit-detail mt-20">{{ JSON.stringify(consistency.mismatches, null, 2) }}</pre></section></template></template>
